window.ScripturaLexicons.BDAG_PART_0239 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-01\" data-source=\"BDAG\" data-search=\"μολύνω verbo manchar; tornar ritualmente impuro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μολύνω</td><td>verbo</td><td>manchar; tornar ritualmente impuro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-02\" data-source=\"BDAG\" data-search=\"μολυσμός, οῦ, ὁ substantivo masculino contaminação; profanação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μολυσμός, οῦ, ὁ</td><td>substantivo masculino</td><td>contaminação; profanação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-03\" data-source=\"BDAG\" data-search=\"μομφή, ῆς, ἡ substantivo feminino censura; queixa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μομφή, ῆς, ἡ</td><td>substantivo feminino</td><td>censura; queixa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-04\" data-source=\"BDAG\" data-search=\"μονάζω verbo viver sozinho; apartar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μονάζω</td><td>verbo</td><td>viver sozinho; apartar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-05\" data-source=\"BDAG\" data-search=\"μονή, ῆς, ἡ substantivo feminino permanência; morada; habitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μονή, ῆς, ἡ</td><td>substantivo feminino</td><td>permanência; morada; habitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-06\" data-source=\"BDAG\" data-search=\"μονογενής, ές adjetivo único; de espécie singular; unigênito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μονογενής, ές</td><td>adjetivo</td><td>único; de espécie singular; unigênito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-07\" data-source=\"BDAG\" data-search=\"μονόλιθος, ον adjetivo de uma só pedra; monolítico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μονόλιθος, ον</td><td>adjetivo</td><td>de uma só pedra; monolítico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-08\" data-source=\"BDAG\" data-search=\"μόνον advérbio (remissão) ver μόνος 2 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μόνον</td><td>advérbio (remissão)</td><td>ver μόνος 2</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-09\" data-source=\"BDAG\" data-search=\"μονοούσιος, ον adjetivo único; singular BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μονοούσιος, ον</td><td>adjetivo</td><td>único; singular</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-10\" data-source=\"BDAG\" data-search=\"μόνος, η, ον adjetivo único; sozinho; somente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μόνος, η, ον</td><td>adjetivo</td><td>único; sozinho; somente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-11\" data-source=\"BDAG\" data-search=\"μονόφθαλμος, ον adjetivo caolho; de um olho só BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μονόφθαλμος, ον</td><td>adjetivo</td><td>caolho; de um olho só</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-12\" data-source=\"BDAG\" data-search=\"μονόω verbo deixar só; ficar sozinho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μονόω</td><td>verbo</td><td>deixar só; ficar sozinho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-13\" data-source=\"BDAG\" data-search=\"μορφή, ῆς, ἡ substantivo feminino forma; aparência; configuração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μορφή, ῆς, ἡ</td><td>substantivo feminino</td><td>forma; aparência; configuração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-14\" data-source=\"BDAG\" data-search=\"μορφόω verbo formar; moldar; tomar forma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μορφόω</td><td>verbo</td><td>formar; moldar; tomar forma</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-15\" data-source=\"BDAG\" data-search=\"μόρφωσις, εως, ἡ substantivo feminino formulação; aparência de piedade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μόρφωσις, εως, ἡ</td><td>substantivo feminino</td><td>formulação; aparência de piedade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-16\" data-source=\"BDAG\" data-search=\"μοσχοποιέω verbo fabricar um bezerro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μοσχοποιέω</td><td>verbo</td><td>fabricar um bezerro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-17\" data-source=\"BDAG\" data-search=\"μόσχος, ου, ὁ substantivo masculino bezerro; novilho; boi BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μόσχος, ου, ὁ</td><td>substantivo masculino</td><td>bezerro; novilho; boi</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-18\" data-source=\"BDAG\" data-search=\"μουσικός, ή, όν adjetivo; substantivo masculino musical; versado em música; músico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μουσικός, ή, όν</td><td>adjetivo; substantivo masculino</td><td>musical; versado em música; músico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-19\" data-source=\"BDAG\" data-search=\"μόχθος, ου, ὁ substantivo masculino trabalho árduo; esforço; fadiga BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μόχθος, ου, ὁ</td><td>substantivo masculino</td><td>trabalho árduo; esforço; fadiga</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0239-20\" data-source=\"BDAG\" data-search=\"μοχλός, οῦ, ὁ substantivo masculino barra; ferrolho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μοχλός, οῦ, ὁ</td><td>substantivo masculino</td><td>barra; ferrolho</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0239-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μολύνω</span>, futuro <span class=\"greek\">μολυνῶ</span> SSol 5:3; 1º aoristo <span class=\"greek\">ἐμόλυνα</span>. Passivo: aoristo <span class=\"greek\">ἐμολύνθην</span>; particípio perfeito <span class=\"greek\">μεμολυμμένος</span> ou <span class=\"greek\">μεμολυσμένος</span> LXX (“manchar, contaminar” Aristoph., Pla. e outros; PSI 1160, 6 [30 a.C.]; LXX; Test12Patr; GrBar).</p><p class=\"entry-text\">① Fazer alguma coisa ficar suja ou manchada, manchar, sujar (Lucian, Anach. 1; Gen 37:31; SSol 5:3) <span class=\"greek\">μεμολυ</span>[<span class=\"greek\">μμένος</span>], impuro, não lavado e, portanto, não puro, acerca de alguém que se aproxima sem a purificação devida de um lugar sagrado que, por sua vez, é puro (<span class=\"greek\">καθαρός</span>) Ox 840, 16. Vestes imaculadas como símbolo de uma vida sem mácula: <span class=\"greek\">ἃ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐμόλυναν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:4</a>.</p><p class=\"entry-text\">② Tornar alguma coisa ritualmente impura, profanar, extensão figurada de 1 (Epict. 2, 8, 13; 2, 9, 17; Porphyr., Abst. 1, 42; Synes., Dreams 10 p. 142d <span class=\"greek\">ἀθέων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μολυνάντων</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">θεῖον</span>; Sir 21:28; Jer 23:11; TestAsh 4:4 <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>; Orig., C. Cels. 7, 64, 27 <span class=\"greek\">τὴν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span> <span class=\"greek\">ὑπόληψιν</span>; Hippol., Ref. 9, 23, 4 <span class=\"greek\">συνείδησιν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἀνόμῳ</span> <span class=\"greek\">κέρδει</span>; Theoph. Ant. 3, 15 [p. 234, 6]) <span class=\"greek\">τ</span>. <span class=\"greek\">χεῖρας</span> (Jos., Vi. 244) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:38</a>, variante de leitura. <span class=\"greek\">ἡ</span> <span class=\"greek\">συνείδησις</span> … <span class=\"greek\">μολύνεται</span>, a consciência é contaminada pelo consumo de carne sacrificada a ídolos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:7</a> (Iren. 1, 6, 3 [Harv. I 55, 11]; Amm. Marc. 15, 2 conscientiam polluebat). Especialmente da imoralidade (Theocr. 5, 87; EpArist 152) <span class=\"greek\">οἳ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">γυναικῶν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐμολύνθησαν</span>, aqueles que não se contaminaram com mulheres <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:4</a> (sobre as dificuldades relacionadas com essa passagem, ver RCharles, Comm.).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολυσμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μολυσμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">μολύνω</span>; Strabo 17, 2, 4; Plut., Mor. 779c; Heliod. 10, 4, 2; 1 Esdr 8:80; 2 Macc 5:27; Jos., C. Ap. 1, 289), contaminação, profanação, em sentido figurado, em contexto sagrado e moral (Vett. Val. 242, 16; Jer 23:15; EpArist 166; TestSim 2:13; Hippol., Ref. 9, 19, 2) <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεύματος</span>, de toda contaminação do corpo e do espírito, isto é, exterior e interiormente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:1</a> (Theoph. Ant. 1, 2 [p. 62, 2]).—DELG s.v. <span class=\"greek\">μολύνω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μομφή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μομφή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Pind. e outros), censura, (motivo de) queixa: <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">μ</span>., ter queixa contra alguém (<span class=\"greek\">ἔχειν</span> <span class=\"greek\">μομφήν</span> <span class=\"greek\">τινι</span>: Pind. e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:13</a>.—DELG s.v. <span class=\"greek\">μέμφομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μονάζω</span> (<span class=\"greek\">μόνος</span>; Cornutus 14 p. 17, 17; Anth. Pal. 5, 66, 1; Iambl., Vi. Pyth. 3, 14; 35, 253; Apollon. Dysc., Synt. 191, 2, Gramm. Gr. II/2 p. 262, 10; 376, 7; escólio a Soph., Aj. 654, Oed. R. 479; Etym. Mag. p. 627, 13; Ps 101:8), viver sozinho, apartar-se 4:10; Hs 9, 26, 3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μονή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μένω</span>; Eur., Hdt. e outros; inscrições, papiros; 1 Macc 7:38; TestAbr, ver adiante).</p><p class=\"entry-text\">① Estado de permanecer num lugar, permanência, estada, demora (Eur. e outros; OGI 527, 5; Philo, Mos. 1, 316) <span class=\"greek\">μονὴν</span> <span class=\"greek\">ποιεῖσθαι</span>, morar, permanecer (Thu. 1, 131, 1; BGU 742; Jos., Ant. 8, 350; 13, 41) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:23</a>.</p><p class=\"entry-text\">② Lugar onde alguém permanece, morada, habitação, aposento, residência (Chariton 1, 12, 1 <span class=\"greek\">μονὴν</span> <span class=\"greek\">ποιεῖν</span>; Paus. 10, 31, 7; OGI 527, 5); de habitações celestes <span class=\"greek\">μοναὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> <span class=\"greek\">μου</span> (TestAbr A 20 p. 104, 2 [Stone p. 56]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:2</a> (OSchaefer, ZNW 32, ’33, 210–17; compreendido em sentido transcendente: RGundry, ZNW 58, ’67, 68–72). <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀμείνονος</span> <span class=\"greek\">τυγχάνειν</span> <span class=\"greek\">μονῆς</span>, alcançar uma morada melhor ApcPt Fgm. 2 p. 12, 22.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονογενής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μονογενής</span>, <span class=\"greek\">ές</span> (<span class=\"greek\">μόνος</span>, <span class=\"greek\">γένος</span>; Hes.; LXX; PsSol 18, 4; TestSol 20:2; TestBenj 9:2; ParJer 7:26; ApcEsdr 6:16; ApcSed 9:2; Joseph., Just.; empréstimo no rabínico); acusativo <span class=\"greek\">μονογενῆ</span> (-<span class=\"greek\">ῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:16</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:17</a> D; também ApcEsdr 6:16).</p><p class=\"entry-text\">① Relativo a ser o único de sua espécie dentro de uma relação específica, único, filho único (assim geralmente, inclusive Judg 11:34; Tob 3:15; 8:17); de filhos: de Isaque, filho único de Abraão (Jos., Ant. 1, 222) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:17</a>. De filho único (PsSol 18:4; TestSol 20:2; ParJer 7:26; Plut., Lycurgus 59 [31, 8]; Jos., Ant. 20, 20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:12</a>; 9:38. De filha única (Diod S 4, 73, 2), de Jairo 8:42. (Sobre o motivo da morte de um filho antes da dos pais, ver EpigrAnat 13, ’89, 128f, n.º 2; 18, ’91, 94 n.º 4 [244/45 d.C.]; GVI n.os 1663–69.)</p><p class=\"entry-text\">② Relativo ao que é o único de sua espécie ou classe, singular, único em espécie; de algo que constitui o único exemplar de sua categoria (Cornutus 27 p, 49, 13 <span class=\"greek\">εἷς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μονογενὴς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">ἐστί</span>. <span class=\"greek\">μονογενῆ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μόνα</span> <span class=\"greek\">ἐστίν</span> = “únicos e sós”; Pla., Timaeus 92c; Theosophien 181, §56, 27). De ave misteriosa, a fênix, 1 Cl 25:2.—Na literatura joanina (ver também ApcEsdr e ApcSed: <span class=\"greek\">ὁ</span> <span class=\"greek\">μονογενής</span> <span class=\"greek\">υἱός</span>; Hippol., Ref. 8, 10, 3; Did., Gen. 89, 18; <span class=\"greek\">ὑμνοῦμέν</span> <span class=\"greek\">γε</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτοῦ</span> Orig., C. Cels. 8, 67, 14; cf. <span class=\"greek\">ἡ</span> <span class=\"greek\">δύναμις</span> <span class=\"greek\">ἐκείνη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. Hippol., Ref. 10, 16, 6), <span class=\"greek\">μονογενὴς</span> <span class=\"greek\">υἱός</span> é empregado somente a respeito de Jesus. As traduções “único”, “singular” podem ser inteiramente adequadas a todas as ocorrências aqui (assim M-M., NRSV e outros; DMoody, JBL 72, ’53, 213–19; FGrant, ATR 36, ’54, 284–87; GPendrick, NTS 41, ’95, 587–600). <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἔδωκεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:16</a> (Philo Bybl. [100 d.C.]: 790 Fgm. 2 cap. 10, 33 Jac. [em Eus., PE 1, 10, 33]: Cronos oferece seu <span class=\"greek\">μονογενὴς</span> <span class=\"greek\">υἱός</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, versículo 18; <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπέσταλκεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:9</a>; cf. Dg 10:2. Quanto à expressão <span class=\"greek\">δόξαν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">μονογενοῦς</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">πατρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:14</a>, ver Hdb. ad loc. e PWinter, Zeitschrift für Rel. u. Geistesgeschichte 5, ’53, 335–65 (inglês). Ver também Hdb. sobre o versículo 18, no qual, ao lado da leitura <span class=\"greek\">μονογενὴς</span> <span class=\"greek\">θεός</span> (considerada por muitos a original), “um unigênito, Deus” (quanto a seu verdadeiro ser, isto é, singularmente divino como Filho de Deus e superior a todos os outros que se alega serem deuses), ou “uma divindade singularmente gerada” (quanto à perspectiva, ver J 10:33–36), encontra-se outra leitura, <span class=\"greek\">ὁ</span> <span class=\"greek\">μονογενὴς</span> <span class=\"greek\">υἱός</span>. MPol 20:2, na doxologia <span class=\"greek\">διὰ</span> <span class=\"greek\">παιδὸς</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μονογενοῦς</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span>. Alguns (por exemplo, WBauer, Hdb.; JBulman, Calvin Theological Journal 16, ’81, 56–79; JDahms, NTS 29, ’83, 222–32) preferem considerar <span class=\"greek\">μ</span>. com sentido algo intensificado em J e 1J, “unigênito” ou “gerado do Único”, em vista da ênfase em <span class=\"greek\">γεννᾶσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεοῦ</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:13</a> e outros); nesse caso, seria análogo a <span class=\"greek\">πρωτότοκος</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:15</a> e outros).—Quanto ao significado de <span class=\"greek\">μονογενής</span> na história das religiões, ver o material em Hdb.3 25f sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:14</a> (também Plut., Mor. 423a <span class=\"greek\">Πλάτων</span> … <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">δή</span> <span class=\"greek\">φησι</span> <span class=\"greek\">δοκεῖν</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">τοῦτον</span> [sc. <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>] <span class=\"greek\">εἶναι</span> <span class=\"greek\">μονογενῆ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγαπητόν</span>; Wsd 7:22, acerca de <span class=\"greek\">σοφία</span>: <span class=\"greek\">ἔστι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">νοερὸν</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">μονογενές</span>.—Vett. Val. 11, 32), bem como a bibliografia ali indicada; também HLeisegang, Der Bruder des Erlösers: <span class=\"greek\">Αγγελος</span> I 1925, 24–33; RBultmann J (comentário, KEK) ’50, 47 nota 2; 55f.—DELG s.v. <span class=\"greek\">μένω</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόλιθος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μονόλιθος</span>, <span class=\"greek\">ον</span> (desde Hdt. 2, 175; Diod S 1, 46, 1; Strabo 9, 5, 16; papiros; Jos., Bell. 7, 290, Ant. 13, 211), feito de uma única pedra, monolítico; de uma torre Hs 9, 9, 7; 9, 13, 5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόνον</h1><div class=\"entry-meta\"><span>advérbio (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μόνον</span>, ver <span class=\"greek\">μόνος</span> 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονοούσιος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μονοούσιος</span>, <span class=\"greek\">ον</span> (ver Lampe, s.v.), único: <span class=\"greek\">ἔδωκέν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">καρπόν</span> … <span class=\"greek\">μονοούσιον</span> <span class=\"greek\">πολυπλάσιον</span>, fruto único e abundante GJs 6:3 (<span class=\"greek\">μονόσιον</span> Bodm.; ver de Strycker p. 226, nota 2).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόνος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μόνος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Pind.+ [como <span class=\"greek\">μοῦνος</span> já em Hom.]).</p><p class=\"entry-text\">① Relativo a ser a única entidade de uma classe, único, só, sozinho, adjetivo.</p><p class=\"entry-text\">ⓐ Com ênfase em ser o único.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Usado com verbos como <span class=\"greek\">εἶναι</span>, <span class=\"greek\">εὑρίσκεσθαι</span>, <span class=\"greek\">καταλείπειν</span>: <span class=\"greek\">μόνος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐκεῖ</span>, estava ali sozinho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:23</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:16</a>. <span class=\"greek\">Λουκᾶς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἐμοῦ</span>, só Lucas está comigo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:11</a>. <span class=\"greek\">εὑρέθη</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">μόνος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:36</a>. <span class=\"greek\">μόνην</span> <span class=\"greek\">με</span> <span class=\"greek\">κατέλειπεν</span> 10:40 (seguido de infinitivo); passivo <span class=\"greek\">κατελείφθη</span> <span class=\"greek\">μόνος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:9</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:1</a>. <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">ὑπελείφθην</span> <span class=\"greek\">μόνος</span>, fiquei sendo o único (Theseus Hist. [época romana]: 453 Fgm. 2 Jac. <span class=\"greek\">μόνος</span> <span class=\"greek\">περιλειφθείς</span>, do único sobrevivente de uma batalha) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:3</a> (cf. 3 Km 19:10, 14; Job 1:15 e outros).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:33</a> [34], variante de leitura.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Usado com substantivo (TestJob 10:1 <span class=\"greek\">τοῖς</span> <span class=\"greek\">ξένοις</span> <span class=\"greek\">μόνοις</span>; AssMos Fgm. d p. 64 <span class=\"greek\">λόγῳ</span> <span class=\"greek\">μόνῳ</span>) <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀθόνια</span> <span class=\"greek\">μόνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:12</a>. <span class=\"greek\">μόνοι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μαθηταὶ</span> <span class=\"greek\">ἀπῆλθον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:22</a>. <span class=\"greek\">μόνος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀρχιερεύς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:7</a>.—Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:4</a> (Jos., Ant. 15, 419 <span class=\"greek\">τ</span>. <span class=\"greek\">ἱερεῦσιν</span> <span class=\"greek\">ἐξὸν</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">μόνοις</span>). <span class=\"greek\">οὗτοι</span> <span class=\"greek\">μόνοι</span> <span class=\"greek\">συνεργοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:11</a>. <span class=\"greek\">μόνῳ</span> <span class=\"greek\">πνεύματι</span> AcPl Ant 13, 18 (<span class=\"greek\">μόνον</span> <span class=\"greek\">πνεύματι</span> Aa I 237, 3). Papias (3:2) <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">ὄγκον</span>.—Usado com pronomes (<span class=\"greek\">μόνος</span> <span class=\"greek\">αὐτός</span>: Nicol. Dam.: 90 Fgm. 130, 23 p. 407, 21 Jac.; Ps.-Demetr., De Eloc. 97; 2 Macc 7:37; Philo, Agr. 39; Jos., Ant. 8, 405, C. Ap. 1, 49); <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">μόνῳ</span> <span class=\"greek\">λατρεύσεις</span> (Dt 6:13, variante de leitura; cf. Jos., Ant. 3, 91 <span class=\"greek\">τοῦτον</span> <span class=\"greek\">μ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:8</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:47</a>; 9:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:15</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">μόνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:4</a>. <span class=\"greek\">σὺ</span> <span class=\"greek\">μόνος</span> … ; (1 Km 21:2; TestZeb 4:12; cf. <span class=\"greek\">σὺ</span> <span class=\"greek\">μόνος</span> ApcSed 15:1), és tu o único? (Field, Notes 82) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:18</a>; <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">μ</span>. (En 6:3; TestJud 3:1; ApcMos 27) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:14</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:6</a>; GJs 1:3; <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">μόνοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:36</a> (cf. Just., D. 19, 2).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Com negação e seguido de <span class=\"greek\">ἀλλά</span>: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἄρτῳ</span> <span class=\"greek\">μόνῳ</span> … , <span class=\"greek\">ἀλλ</span>’ … (Dt 8:3) Mt 4:4=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:4</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> … <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">πολλοστόν</span> AcPlCor 2:27 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">μ</span>. … , <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καί</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:4</a>; 2J 1. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐγράφη</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">μόνον</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:23</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μόνον</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:27</a>. Pleonástico com <span class=\"greek\">εἰ</span> <span class=\"greek\">μή</span> após uma negação: não ... exceto ... somente (Lydus, Magist. 1, 18 p. 22, 22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:4</a>; 17:8; 24:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:8</a>, variante de leitura (em lugar de <span class=\"greek\">ἀλλὰ</span> … <span class=\"greek\">μόνον</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:21</a>; 6:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:4</a>, variante de leitura.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. <span class=\"greek\">μόνος</span> <span class=\"greek\">θεός</span> (cf. Simonides, Fgm. 4, 7 Diehl <span class=\"greek\">θεὸς</span> <span class=\"greek\">μόνος</span>; Da 3:45; SibOr 3, 629; PGM 13, 983), o único Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:17</a>; Jd 25 (GDelling, TLZ 77, ’52, 469–76). Com artigo precedente: <span class=\"greek\">ὁ</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">θ</span>. (EpArist 139; Philo, Fuga 71; Just., D. 126, 2 <span class=\"greek\">τοῦ</span> <span class=\"greek\">μόνου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγεννήτου</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">υἱόν</span>; <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">μόνος</span> 4 Km 19:15, 19; Ps 85:10; Is 37:20. Cf. ENorden, Agn. Theos 1913, 245, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:44</a> (sem <span class=\"greek\">θεοῦ</span>, variante de leitura). <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀληθινὸς</span> <span class=\"greek\">θεός</span>, o único Deus verdadeiro 17:3 (Demochares [cerca de 300 a.C.]: 75 Fgm. 2 Jac. <span class=\"greek\">τὸν</span> <span class=\"greek\">Δημήτριον</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">Ἀθηναῖοι</span> <span class=\"greek\">ἐδέχοντο</span> … <span class=\"greek\">ἐπᾴδοντες</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">εἴη</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἀληθινός</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἄλλοι</span> <span class=\"greek\">καθεύδουσιν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀποδημοῦσιν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰσίν</span>. <span class=\"greek\">γεγονὼς</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">εἴη</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">Ποσειδῶνος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἀφροδίτης</span>, “os atenienses acolheram Demétrio ... adulando-o com a suposição de que ele fosse o único deus verdadeiro, ao passo que os demais dormiam, viajavam ou simplesmente não existiam; e de que ele provavelmente descendesse de Posídon e Afrodite”). <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀληθινοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μόνου</span> <span class=\"greek\">κυρίου</span> 1 Cl 43:6 (cf. Just., D. 55, 2 <span class=\"greek\">κύριος</span> <span class=\"greek\">μ</span>.). <span class=\"greek\">μ</span>. <span class=\"greek\">σοφὸς</span> <span class=\"greek\">θεός</span>, o único Deus sábio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:27</a> (Philo, Fuga 47 <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">σοφός</span>; Heraclitus, Fgm. 32 <span class=\"greek\">ἓν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σοφὸν</span> <span class=\"greek\">μοῦνον</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">δεσπότης</span>, o único que é senhor Jd 4 (cf. Jos., Bell. 7, 323; 410). <span class=\"greek\">ὁ</span> <span class=\"greek\">μακάριος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">δυνάστης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:15</a>.—Versículo 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:4</a>.</p><p class=\"entry-text\">ⓑ Com ênfase em estar desamparadamente só: sozinho, abandonado, desamparado (Hom. e outros; BGU 180, 23 [172 d.C.] <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">πρεσβύτης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">τυγχάνων</span>; 385, 4; Wsd 10:1; TestJos 1:6; La 1:1) <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀφῆκέν</span> <span class=\"greek\">με</span> <span class=\"greek\">μόνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:29</a>; 16:32ab (<span class=\"greek\">ἀφ</span>. <span class=\"greek\">μόν</span>. como em Dio Chrys. 46 [63], 2).</p><p class=\"entry-text\">ⓒ Com ênfase no isolamento: isolado, separado dos demais (cf. Bar 4:16; En 28:1; TestJud 5:3; JosAs 2:16; Ar. 11:2) <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κόκκος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σίτου</span> … <span class=\"greek\">ἀποθάνῃ</span>, <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">μένει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:24</a>. Em Hv 3, 9, 2, <span class=\"greek\">μ</span>. refere-se a cristãos egoístas que se isolam das necessidades dos famintos.</p><p class=\"entry-text\">② Marcador de limitação: só, somente, com o neutro <span class=\"greek\">μόνον</span> empregado como advérbio (Aeschyl., Hdt. e outros).</p><p class=\"entry-text\">ⓐ Restringindo a ação ou estado ao que é designado pelo verbo (TestAbr A 4 p. 81, 25 [Stone p. 10]; TestJos 16:4; JosAs 24:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:21</a>; 14:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:39</a>; 15:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:7</a>; Hv 3, 2, 1.—<span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:8</a>.</p><p class=\"entry-text\">ⓑ Com substantivo (Just., A I, 22, 1 <span class=\"greek\">μ</span>. <span class=\"greek\">ἄνθρωπος</span>) ou pronome, para distinguir uma pessoa ou coisa das outras: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:47</a>; 10:42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:10</a>; Hm 12, 4, 7; <span class=\"greek\">τοῦτο</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:2</a>.</p><p class=\"entry-text\">ⓒ Usado com negações.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">μ</span>. <span class=\"greek\">μή</span>, apenas não, não somente (POxy 2153, 22; TestJob 45:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:13</a>. <span class=\"greek\">οὐ</span> (<span class=\"greek\">μὴ</span>) <span class=\"greek\">μ</span>. 4:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:22</a>; 2:24 (ver <span class=\"greek\">β</span> abaixo). <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>. … <span class=\"greek\">ἀλλά</span> (sem <span class=\"greek\">καί</span> quando o segundo membro inclui o primeiro. X., Cyr. 1, 6, 16; Diod S 4, 15, 1; Dio Chrys. 1, 22; 62; 64 [14], 7; Just., A I, 2, 1; B-D-F §448, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:26</a> (mas alguns manuscritos acrescentam <span class=\"greek\">καί</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:6</a>. <span class=\"greek\">οὐ</span> (ou <span class=\"greek\">μὴ</span>) <span class=\"greek\">μ</span>. … , <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καί</span>, não somente ... mas também (PMich 209, 12 [cerca de 200 d.C.]; TestJos 10:3; Jos., Bell. 3, 102; Just., A I, 5, 4 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:13</a>; 26:29; 27:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:32</a>; 9:24; 13:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:10</a>, 21; 9:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:18</a>; Qua. <span class=\"greek\">οὐ</span> (<span class=\"greek\">μὴ</span>) … <span class=\"greek\">μ</span>., <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.52\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:52</a>; 12:9; 13:9; 17:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:12</a>, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:5</a> e outros. <span class=\"greek\">οὐ</span> … <span class=\"greek\">μόνον</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:2</a>. <span class=\"greek\">οὐδέπω</span> … , <span class=\"greek\">μ</span>. <span class=\"greek\">δέ</span>, ainda não ... mas ... somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:16</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">δέ</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καί</span>, não somente isto, mas também (elipse com complementação do que precede imediatamente; Mitt-Wilck. II/2, 26, 9=27, 9 [108 a.C.]; cf. Sb 7616 [II d.C.]; Wsd 19:15; TestJob 35:1; Just., A I, 49, 5; B-D-F §479, 1; ver Rob. 1201ff) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:3</a>, 11; 8:23; 9:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:19</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καί</span> (TestZeb 3:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:13</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">μ</span>., <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μᾶλλον</span>, não somente ... mas muito mais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:12</a>. <span class=\"greek\">οὐδὲν</span> (<span class=\"greek\">μηδὲν</span>) … <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> … <span class=\"greek\">μόνον</span> (TestAbr B 11 p. 116, 3 [Stone p. 80]; TestJob 11:7; Ar 13, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:8</a>. <span class=\"greek\">μηδενὶ</span> … <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:19</a>. Sobre 1–2c, ver KBeyer, Semitische Syntax im NT ’62, 126–29.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Isoladamente: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">μόνον</span>, não pela fé considerada isoladamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:24</a> (NEB: “não pela fé em si mesma”; Goodsp.: “não simplesmente por ter fé”; semelhantemente Moffatt; ver Athanasius Alexandrinus, De Virginitate PGM 28, 260c; cf. Clem., Strom. 3, 15 <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐνουχία</span> <span class=\"greek\">δικαιοῖ</span> = ser eunuco, por si só, não justifica. Ver também <span class=\"greek\">πίστις</span> 2d<span class=\"greek\">δ</span>.)</p><p class=\"entry-text\">ⓓ <span class=\"greek\">ἵνα</span> <span class=\"greek\">μόνον</span>, unicamente para que 12:8; <span class=\"greek\">μόνον</span> <span class=\"greek\">ἵνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:12</a>.</p><p class=\"entry-text\">③ <span class=\"greek\">κατὰ</span> <span class=\"greek\">μόνας</span> (Thu. 1, 32, 5; X., Mem. 3, 7, 4; Menand., Epitr. 988 S. [658 Kö.], Fgm. 146 Kö.; Polyb. 4, 15, 11; Diod S 4, 51, 16; Gen 32:16; Ps 4:9; Jer 15:17; 1 Macc 12:36; TestJos 4:1; Jos., Vi. 326, Ant. 17, 336 e outros.—Também escrito <span class=\"greek\">καταμόνας</span>; cf. BGU 813, 15 em APF 2, 1903, 97), sozinho <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μ</span>., estar sozinho (Syntipas p. 9, 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:10</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:18</a>; Hm 11:8.—B-D-F §241, 6.—B. 937. DELG. Schmidt, Syn. IV 535–39. M-M. EDNT. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόφθαλμος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μονόφθαλμος</span>, <span class=\"greek\">ον</span> (Hdt. e outros; rejeitado pelos aticistas no sentido de “privado de um olho”, em favor de <span class=\"greek\">ἑτερόφθαλμος</span> [Phryn. 136 Lob.], mas usado nesse sentido na linguagem coloquial posterior: Polyb. 5, 67, 6; Strabo 2, 1, 9; Lucian, Ver. Hist. 1, 3; Ps.-Apollod. 2, 8, 3, 4 e outros. Talvez BGU 1196, 97 [I a.C.], ver HBraunert, ZKG 70, ’59, 316, com referência a PBrux inv. E 7616 X, 21 e PMich 425, 12 [ambos II d.C.]), caolho, de um olho só <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:47</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μονόω</span>, particípio perfeito passivo <span class=\"greek\">μεμονωμένος</span> (<span class=\"greek\">μόνος</span>; Hom. e outros; Musonius 73, 1 H.), deixar só; passivo, ficar só, ser deixado sozinho (Thu. 2, 81, 5; 5, 58, 2; Nicol. Dam.: 90 Fgm. 130, 30 p. 416, 15 Jac.; JosAs 13 [p.57, 5 Bat.] cód. A; Philo; Jos., Ant. 5, 280, Vi. 95; Tat. 14, 1); de viúva, <span class=\"greek\">μεμονωμένη</span>, foi deixada só (cf. Anacreontea 37, 13 Preis.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:5</a>.—DELG s.v. <span class=\"greek\">μόνος</span> 8. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορφή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μορφή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Hom.+), forma, aparência exterior, configuração, de modo geral, da forma corpórea 1 Cl 39:3; ApcPt 4:13 (Job 4:16; ApcEsdr 4:14 p. 28, 16 Tdf.; SJCh 78, 13). Da configuração ou forma de estátuas (Jos., Vi. 65; Iren. 1, 8, 1 [Harv. I 67, 11]) Dg 2:3. De aparições em visões etc., semelhantes a pessoas (Callisthenes [IV a.C.]: 124 Fgm. 13 p. 644, 32 Jac. [em Athen. 10, 75, 452b] <span class=\"greek\">Λιμὸς</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">γυναικὸς</span> <span class=\"greek\">μορφήν</span>; Diod S 3, 31, 4 <span class=\"greek\">ἐν</span> <span class=\"greek\">μορφαῖς</span> <span class=\"greek\">ἀνθρώπων</span>; TestAbr A 16 p. 97, 11 [Stone p. 42] <span class=\"greek\">ἀρχαγγέλου</span> <span class=\"greek\">μορφὴν</span> <span class=\"greek\">περικείμενος</span>; Jos., Ant. 5, 213, um mensageiro do céu <span class=\"greek\">νεανίσκου</span> <span class=\"greek\">μορφῇ</span>): da assembleia de Deus, a igreja Hv 3, 10, 2; 9; 3, 11, 1; 3, 13, 1; Hs 9, 1, 1; do anjo do arrependimento <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἠλλοιώθη</span>, sua aparência havia mudado m 12, 4, 1. De Cristo (<span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀνθρώπου</span> TestBenj 10:7; Just., D. 61, 1; Tat. 2, 1; Hippol., Ref. 5, 16, 10. Cf. Did., Gen. 56, 18; de divindades <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνθρωπίνῃ</span> <span class=\"greek\">μορφῇ</span>: Iambl., Vi. Pyth. 6, 30; cf. Philo, Abr. 118) <span class=\"greek\">μορφὴν</span> <span class=\"greek\">δούλου</span> <span class=\"greek\">λαβών</span>, assumiu a forma de escravo = expressão de servilidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:7</a> (com <span class=\"greek\">σχῆμα</span>, como em Aristot., Cat. 10a, 11f, PA 640b, 30–36). Isso contrasta com a expressão de divindade no Cristo preexistente: <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὑπάρχων</span>, embora estivesse na forma de Deus (cf. OGI 383, 40f: o corpo de Antíoco é a estrutura que sustenta sua <span class=\"greek\">μ</span>., ou identidade essencial, como descendente de divindades; analogamente, a fragilidade humana [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:7</a>] se torna a estrutura de sustentação da condição servil de Cristo e, portanto, de sua <span class=\"greek\">κένωσις</span> [sobre a aparência que alguém projeta, cf. o epitáfio EpigrAnat 17, ’91, 156, n.º 3, 5–8]; sobre <span class=\"greek\">μορφὴ</span> <span class=\"greek\">θεοῦ</span>, cf. Orig., C. Cels. 7, 66, 21; Pla., Rep. 2, 380d; 381bc; X., Mem. 4, 3, 13; Diog. L. 1, 10, os egípcios dizem <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰδέναι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μορφήν</span>; Philo, Leg. ad Gai. 80; 110; Jos., C. Ap. 2, 190; Just., A I, 9, 1; PGM 7, 563; 13, 272; 584.—Rtzst., Mysterienrel.3 357f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:6</a>. O Cristo ressuscitado <span class=\"greek\">ἐφανερώθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτέρᾳ</span> <span class=\"greek\">μορφῇ</span>, apareceu em outra forma <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:12</a> (da transfiguração de Jesus: <span class=\"greek\">ἔδειξεν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔνδοξον</span> <span class=\"greek\">μορφὴν</span> <span class=\"greek\">ἑαυτοῦ</span> Orig., C. Cels. 6, 68, 23). Para bibliografia, ver <span class=\"greek\">ἁρπαγμός</span> e <span class=\"greek\">κενόω</span> 1b; RMartin, ET 70, ’59, 183f.—DSteenberg, The Case against the Synonymity of <span class=\"greek\">μορφή</span> and <span class=\"greek\">εἰκών</span>: JSNT 34, ’88, 77–86; GStroumsa, HTR 76, ’83, 269–88 (contexto semítico).—DELG. Schmidt, Syn. IV 345–60. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορφόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μορφόω</span> (<span class=\"greek\">μορφή</span>), particípio do 1º aoristo <span class=\"greek\">μορφώσαντες</span> (Just., A I, 9, 1). Passivo: aoristo <span class=\"greek\">ἐμορφώθην</span>; particípio perfeito <span class=\"greek\">μεμορφωμένος</span> (Philo, Joseph.) (Aratus, Phaen. 375; Nilus: Anth. Pal. 1, 33, 1; Is 44:13 Q à margem e Aq.; Philo, Plant. 3; Ps.-Philo, De Mundo 13; SibOr 4, 182; Jos., Ant. 15, 329; Just., A I, 5, 4 <span class=\"greek\">τοῦ</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">μορφωθέντος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">γενομένου</span>; Ath., R. 3 p. 51, 16), formar, dar forma, moldar, na voz ativa PtK 2 p. 14, 13. Passivo: tomar forma, ser formado (Theophr., CP 5, 6, 7; Diod S 3, 51, 3), figuradamente, como na formação de um embrião (Galen XIX p. 181 K. <span class=\"greek\">ἔμβρυα</span> <span class=\"greek\">μεμορφωμένα</span>; Philo, Spec. Leg. 3, 117) <span class=\"greek\">μέχρις</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">μορφωθῇ</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>, até que Cristo seja formado em vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:19</a> (RHermann, TLZ 80, ’55, 713–26).—DELG s.v. <span class=\"greek\">μορφή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόρφωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μόρφωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μορφόω</span>; Theophr., CP 3, 7, 4 e outros; TestBenj 10:1), estado de possuir uma estrutura formal, concretização, formulação, forma; de um judeu <span class=\"greek\">ἔχοντα</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώσεως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νόμῳ</span>, tu que possuis a concretização ou formulação do conhecimento e da verdade no livro da Lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:20</a> (<span class=\"greek\">νόμος</span> = “livro da Lei”, como em Jos., Bell. 2, 292, Ant, 12, 256). De mestres do erro <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">μ</span>. <span class=\"greek\">εὐσεβείας</span>, que conservam uma forma de piedade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:5</a> (cf. Philo, Plant. 70 <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">εἰσί</span> <span class=\"greek\">τινες</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐπιμορφαζόντων</span> <span class=\"greek\">εὐσέβειαν</span> <span class=\"greek\">κτλ</span>. = “pois ainda agora há alguns que assumem uma aparência de piedade”. O prefixo <span class=\"greek\">ἐπί</span> contribui com o componente semântico que aponta para mera forma exterior. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:5</a>, a ideia de mera forma exterior deriva do contexto).—DELG s.v. <span class=\"greek\">μορφή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοσχοποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μοσχοποιέω</span> (<span class=\"greek\">μόσχος</span>, <span class=\"greek\">ποιέω</span>), 1º aoristo <span class=\"greek\">ἐμοσχοποίησα</span> (somente em escritores cristãos, como Just.; <span class=\"greek\">εἰδωλοποιέω</span> em Pla.+), fabricar um bezerro, do bezerro de ouro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:41</a> (em lugar de <span class=\"greek\">ἐποίησε</span> <span class=\"greek\">μόσχον</span> Ex 32:4).—M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόσχος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μόσχος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, bezerro, novilho ou boi (assim em trágicos, Hdt. +) <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">σιτευτός</span> (Judg 6:25 A, 28 A; Jer 26:21), bezerro cevado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:23</a>, 27, 30. Como animal apocalíptico (cf. Ezk 1:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:7</a>. Como animal sacrificial (Mitt-Wilck. I/2, 87–89) 1 Cl 52:2 (Ps 68:32); GJs 4:3. Especialmente na oferta pelo pecado no Dia da Expiação <span class=\"greek\">αἷμα</span> <span class=\"greek\">τράγων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μόσχων</span>, sangue de bodes e bezerros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:12</a>; cf. versículo 19. Designa a “novilha vermelha” (Num 19), interpretada como significando Cristo 8:2.—B. 155. DELG s.v. 1 <span class=\"greek\">μόσχος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo; substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μουσικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span>, relativo à música, musical, versado em música (assim em Aristoph. e outros; inscrições, papiros, LXX; TestBenj 11:3; Jos., Ant. 16, 137 e outros [<span class=\"greek\">ἡ</span> <span class=\"greek\">μουσική</span>]; Just. [<span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>.]); substantivado <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>., o músico (X., Cyr. 1, 6, 38; Cornutus 32 p. 67, 17 <span class=\"greek\">μ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">κιθαριστής</span>; OGI 383, 162; PFlor 74, 6; POxy 1275, 9 <span class=\"greek\">συμφωνίας</span> <span class=\"greek\">αὐλητῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μουσικῶν</span>; Ezk 26:13; Philo), junto de harpistas, flautistas e trombeteiros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.22\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:22</a>.—EWerner, The Sacred Bridge (Liturgy and Music) ’59.—DELG s.v. <span class=\"greek\">μοῦσα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόχθος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μόχθος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hes. e X.+; PRyl 28, 117; Kaibel 851, 1; LXX; TestAbr B 9 p. 114, 2 [Stone p. 76]; TestJob 24:2; TestJud 18:4; Apc4Esdr Fgm. a [com <span class=\"greek\">κόπος</span>]; SibOr 2, 272; Philo, Mos. 1, 284), trabalho, esforço, fadiga, dificuldade, com <span class=\"greek\">κόπος</span> (Proverb. Aesopi 11 P.; Anth. Pal. 1, 47, 3; 1, 90, 4; Jer 20:18, variante de leitura; cf. Job 2:9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:8</a>; Hs 5, 6, 2.—<span class=\"greek\">πόνος</span> 2, final.—DELG. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0239-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοχλός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μοχλός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (desde Hom.), barra, ferrolho (assim em Aeschyl., Thu. e outros; inscrições, LXX; JosAs 10:5; ApcEsdr 4:25 p. 28, 30 Tdf.; Jos., Bell. 6, 293 <span class=\"greek\">μ</span>. <span class=\"greek\">σιδηρόδετος</span>; empréstimo no rabínico) <span class=\"greek\">μ</span>. <span class=\"greek\">σιδηροῦς</span> <span class=\"greek\">συγκλᾶν</span>, quebrar ferrolhos de ferro 11:4 (Is 45:2).—DELG.</p></section></article>"};
